mapper.select:
SELECT COALESCE(SUM(budget_amount), 0)
FROM budget_preparation_detail bd
INNER JOIN budget_preparation bp ON bd.sheet_id = bp.id
WHERE bd.subject_code = #{subjectCode}
  AND bp.org_id = #{deptId}
  AND bp.budget_year = #{budgetYear}
  AND bp.budget_month = #{budgetMonth}
  AND bp.status = 'Approved'

mapper.update:
UPDATE budget_preparation_detail bd
INNER JOIN budget_preparation bp ON bd.sheet_id = bp.id
SET bd.budget_amount = bd.budget_amount + #{amount},
    bd.update_time = NOW()
WHERE bd.subject_code = #{subjectCode}
  AND bp.org_id = #{deptId}
  AND bp.budget_year = #{budgetYear}
  AND bp.budget_month = #{budgetMonth}
  AND bp.status = 'Approved'

mapper.select:
SELECT COALESCE((
    SELECT SUM(bd.budget_amount)
    FROM budget_preparation_detail bd
    INNER JOIN budget_preparation bp ON bd.sheet_id = bp.id
    WHERE bd.subject_code = #{subjectCode}
      AND bp.org_id = #{deptId}
      AND bp.budget_year = #{budgetYear}
      AND bp.budget_month = #{budgetMonth}
      AND bp.status = 'Approved'
), 0)
-
COALESCE((
    SELECT SUM(e.amount)
    FROM fee_expense_bill e
    WHERE e.calc_budget_subject = #{subjectCode}
      AND e.dept_id = #{deptId}
      AND e.status = 'APPROVED'
), 0)

mapper.update:
UPDATE budget_preparation_detail bd
INNER JOIN budget_preparation bp ON bd.sheet_id = bp.id
SET bd.budget_amount = #{amount},
    bd.update_time = NOW()
WHERE bd.subject_code = #{subjectCode}
  AND bp.org_id = #{deptId}
  AND bp.budget_year = #{budgetYear}
  AND bp.budget_month = #{budgetMonth}
  AND bp.status = 'Approved'

